import sand3d as s3d


def bridge_mounted_revolute_chain():
    br = bridge_part()
    f = s3d.local(br, 80, 0, 420)
    pro = s3d.at(proximal_link(), on=f)
    s3d.joint("root_pivot", pro, f, kind="revolute", axis="+Y", range=(-63.025, 63.025))
    e = s3d.local(pro, 340, 0, 0)
    tab = s3d.at(distal_tab(), on=e)
    s3d.joint("elbow_pivot", tab, e, kind="revolute", axis="+Y", range=(-77.35, 77.35))
    return s3d.assembly("bridge_mounted_revolute_chain", br, pro, tab)


def bridge_part():
    blue = "#1a3857"
    q = [
        s3d.at(s3d.extrude("base_plate", s3d.rect(280, 520), 30, both=True), x=-45, z=15),
        s3d.at(s3d.extrude("post_0", s3d.rect(65, 55), 405, both=True), x=-70, y=-220, z=217),
        s3d.at(s3d.extrude("post_1", s3d.rect(65, 55), 405, both=True), x=-70, y=220, z=217),
        s3d.at(s3d.extrude("top_bridge", s3d.rect(120, 520), 60, both=True), x=-45, z=400),
        s3d.at(s3d.extrude("clevis_neck", s3d.rect(30, 118), 75, both=True), x=10, z=420),
    ]
    for y, n in [(-41, "clevis_cheek_0"), (41, "clevis_cheek_1")]:
        q.append(
            s3d.at(
                s3d.extrude(n, s3d.rect(125, 120, r=16) - s3d.circle(36), 18, both=True),
                x=80,
                y=y,
                z=420,
                rx=90,
            )
        )
    q.append(
        s3d.material(
            s3d.at(s3d.extrude("root_pin", s3d.circle(28), 130, both=True), x=80, z=420, rx=90),
            "steel",
            color="#c7c2b3",
        )
    )
    for y, n in [(-67, "root_pin_head_0"), (67, "root_pin_head_1")]:
        q.append(
            s3d.material(
                s3d.at(s3d.extrude(n, s3d.circle(44), 6, both=True), x=80, y=y, z=420, rx=90),
                "steel",
                color="#c7c2b3",
            )
        )
    for i, x in enumerate(q):
        if i not in (5, 6, 7, 8):
            s3d.material(x, "painted_metal", color=blue)
    return s3d.group("bridge", *q)


def proximal_link():
    body = profile_plate(
        "tapered_body", [(0, 50), (270, 32), (302, 0), (270, -32), (0, -50), (-50, 0)], 38, 36, 0
    )
    f0 = profile_plate(
        "fork_cheek_0",
        [(250, 28), (340, 36), (376, 0), (340, -36), (250, -28), (222, 0)],
        16,
        26,
        340,
    )
    f0 = s3d.at(f0, y=-26.5)
    f1 = s3d.transform(s3d.copy(f0), y=53)
    pin = s3d.material(
        s3d.at(s3d.extrude("elbow_pin", s3d.circle(20), 91, both=True), x=340, rx=90),
        "steel",
        color="#c7c2b3",
    )
    h0 = s3d.material(
        s3d.at(s3d.extrude("elbow_pin_head_0", s3d.circle(32), 5, both=True), x=340, y=-47, rx=90),
        "steel",
        color="#c7c2b3",
    )
    h1 = s3d.material(
        s3d.at(s3d.extrude("elbow_pin_head_1", s3d.circle(32), 5, both=True), x=340, y=47, rx=90),
        "steel",
        color="#c7c2b3",
    )
    r = s3d.material(s3d.at(s3d.torus("root_bushing_face", 39, 9), rx=90), "brass", color="#bd7a38")
    return s3d.group("proximal_link", body, f0, f1, pin, h0, h1, r)


def profile_plate(name, pts, th, hole_start, hole_end=None):
    p = s3d.poly(pts) - s3d.at(s3d.circle(hole_start), x=0)
    if hole_end is not None:
        p = p - s3d.at(s3d.circle(26), x=hole_end)
    return s3d.material(
        s3d.at(s3d.extrude(name, p, th, both=True), rx=90), "painted_metal", color="#3b454d"
    )


def distal_tab():
    p = (
        s3d.poly([(0, 32), (240, 24), (264, 0), (240, -24), (0, -32), (-32, 0)])
        - s3d.circle(26)
        - s3d.at(s3d.circle(16), x=240)
    )
    b = s3d.at(s3d.extrude("compact_tab", p, 26, both=True), rx=90)
    l = s3d.at(s3d.extrude("end_tab_hole_liner", s3d.circle(22), 4, both=True), x=240, rx=90)
    s3d.material(b, "aluminium", color="#9ea8ad")
    s3d.material(l, "rubber", color="#08090a")
    return s3d.group("distal_tab", b, l)

import sand3d as s3d
import math


def garden_gate():
    fence_parts = []

    def boxpart(name, size, x, y, z, mat="oak", color="#8c5c2e", ry=0, rx=0):
        a = s3d.extrude(name, s3d.rect(size[0], size[1]), size[2], both=True)
        return s3d.material(s3d.at(a, x=x, y=y, z=z, rx=rx, ry=ry), mat, color=color)

    def cylpart(name, d, h, x, y, z, mat="steel", color="#262421", rx=0):
        return s3d.material(
            s3d.at(s3d.cylinder(name, d, h), x=x, y=y, z=z, rx=rx), mat, color=color
        )

    def spherepart(name, d, x, y, z, mat="plastic", color="#21541f"):
        return s3d.material(s3d.at(s3d.sphere(name, d), x=x, y=y, z=z - d / 2), mat, color=color)

    fence_parts += [
        boxpart("gravel_strip", (3800, 540, 40), 450, 0, -20, "concrete", "#473d30"),
        boxpart("hinge_post", (160, 160, 1650), -100, 0, 825),
        boxpart("hinge_post_cap", (180, 180, 45), -100, 0, 1672.5, "walnut", "#613b1c"),
        boxpart("latch_post", (160, 160, 1650), 1150, 0, 825),
        boxpart("latch_post_cap", (180, 180, 45), 1150, 0, 1672.5, "walnut", "#613b1c"),
    ]
    for p, c, l in [("left", -780, 1200), ("right", 1765, 1070)]:
        for z, r in [(490, "lower_rail"), (1060, "upper_rail")]:
            fence_parts.append(boxpart(p + "_" + r, (l, 55, 95), c, 0, z))
    for side, xs in [
        ("left", [-1300, -1140, -980, -820, -660, -500, -340]),
        ("right", [1320, 1480, 1640, 1800, 1960, 2120, 2280]),
    ]:
        for i, x in enumerate(xs):
            fence_parts += [
                boxpart(f"{side}_picket_{i}", (58, 45, 1120), x, 0, 560),
                boxpart(f"{side}_picket_cap_{i}", (70, 47, 55), x, 0, 1147, "walnut", "#613b1c"),
            ]
    for i, x in enumerate([-1180, -1020, 1920, 2100]):
        fence_parts += [
            cylpart(f"shrub_stem_{i}", 28, 160, x, -200, 0, "plastic", "#21541f"),
            spherepart(f"shrub_clump_{i}", 150, x, -200, 170),
        ]
    for i, zc in enumerate((350, 750, 1150)):
        for j, dz in enumerate((-55, 55)):
            z = zc + dz
            fence_parts += [
                cylpart(f"fixed_knuckle_{i}_{j}", 36, 45, 0, -86, z),
                boxpart(f"fixed_hinge_leaf_{i}_{j}", (80, 14, 45), -55, -85, z),
            ]
            for k, sx in enumerate((-75, -36)):
                fence_parts.append(
                    cylpart(
                        f"fixed_hinge_screw_{i}_{j}_{k}", 13, 6, sx, -95, z, "steel", "#6b6e66", 90
                    )
                )
    fence_parts += [
        boxpart("strike_plate", (12, 14, 220), 1064, -86, 840),
        boxpart("lower_keeper", (65, 26, 18), 1042.5, -103, 805, "steel", "#262421"),
        boxpart("upper_keeper", (65, 26, 18), 1042.5, -103, 875, "steel", "#262421"),
    ]
    for z in (760, 920):
        fence_parts.append(
            cylpart(f"strike_screw_{z / 1000:.2f}", 15, 6, 1058, -96, z, "steel", "#6b6e66", 90)
        )
    fence = s3d.group("fence", *fence_parts)
    gp = [
        boxpart("hinge_stile", (90, 55, 1240), 85, 36, 720),
        boxpart("latch_stile", (90, 55, 1240), 985, 36, 720),
        boxpart("bottom_rail", (990, 55, 90), 535, 36, 170),
        boxpart("middle_rail", (990, 55, 75), 535, 36, 720),
        boxpart("top_rail", (990, 55, 90), 535, 36, 1280),
    ]
    for i, x in enumerate([240, 360, 480, 600, 720, 840]):
        gp += [
            boxpart(f"gate_picket_{i}", (55, 36, 1080), x, 40, 680),
            boxpart(f"gate_picket_cap_{i}", (64, 38, 50), x, 40, 1245, "walnut", "#613b1c"),
        ]
    gp.append(
        boxpart(
            "diagonal_brace",
            (math.hypot(780, 940), 45, 70),
            540,
            70,
            710,
            "walnut",
            "#613b1c",
            -math.degrees(math.atan2(940, 780)),
        )
    )
    for i, zc in enumerate((350, 750, 1150)):
        gp += [
            cylpart(f"swing_knuckle_{i}", 36, 65, 0, 0, zc),
            boxpart(f"swing_hinge_leaf_{i}", (205, 14, 55), 117.5, 2, zc),
        ]
        for k, x in enumerate((60, 145)):
            gp.append(
                cylpart(f"swing_hinge_screw_{i}_{k}", 13, 6, x, -8, zc, "steel", "#6b6e66", 90)
            )
    gp += [
        boxpart("latch_backplate", (70, 11, 115), 930, 3, 840, "steel", "#262421"),
        cylpart("latch_bushing", 34, 6, 930, -2, 840, "steel", "#6b6e66", 90),
    ]
    gate = s3d.group("gate", *gp)
    handle = s3d.group(
        "latch_handle",
        cylpart("handle_spindle", 28, 16, 0, -8, 0, "steel", "#6b6e66", 90),
        boxpart("handle_lever", (280, 12, 35), -140, -21, 0, "steel", "#262421"),
        spherepart("handle_grip", 52, -305, -21, 0, "steel", "#262421"),
        boxpart("latch_tongue", (135, 12, 26), 67.5, -21, 0, "steel", "#262421"),
    )
    f = s3d.local(fence, 0, -86, 0)
    gate = s3d.at(gate, on=f)
    s3d.joint("gate_hinge", gate, f, kind="revolute", axis="+Z", range=(0, 94.538))
    g = s3d.local(gate, 930, -2.5, 840)
    handle = s3d.at(handle, on=g)
    s3d.joint("handle_pivot", handle, g, kind="revolute", axis="+Y", range=(-10.313, 37.242))
    return s3d.assembly("garden_gate", fence, gate, handle)

import sand3d as s3d


def base_cabinet_double_shaker_doors():
    carcass = carcass_part()
    ld = door_part("left_door", 1)
    rd = door_part("right_door", -1)
    lk = knob_part("left_knob")
    rk = knob_part("right_knob")
    f = s3d.local(carcass, -372, 310, 16)
    ld = s3d.at(ld, on=f)
    s3d.joint(
        "carcass_to_left_door", ld, f, kind="revolute", axis="+Z", range=(0, 1.85 * 180 / 3.14)
    )
    f = s3d.local(carcass, 372, 310, 16)
    rd = s3d.at(rd, on=f)
    s3d.joint(
        "carcass_to_right_door", rd, f, kind="revolute", axis="+Z", range=(-1.85 * 180 / 3.14, 0)
    )
    f = s3d.local(ld, 318, 10, 444.14)
    lk = s3d.at(lk, on=f)
    s3d.joint("left_door_to_left_knob", lk, f, kind="continuous", axis="+Y")
    f = s3d.local(rd, -318, 10, 444.14)
    rk = s3d.at(rk, on=f)
    s3d.joint("right_door_to_right_knob", rk, f, kind="continuous", axis="+Y")
    return s3d.assembly("base_cabinet_double_shaker_doors", carcass, ld, rd, lk, rk)


def bx(name, w, d, h, x=0, y=0, z=0):
    return s3d.at(s3d.extrude(name, s3d.rect(w, d), h, both=True), x=x, y=y, z=z)


def cy(name, r, h, x=0, y=0, z=0, rx=0):
    return s3d.at(s3d.extrude(name, s3d.circle(2 * r), h, both=True), x=x, y=y, z=z, rx=rx)


def carcass_part():
    p = []

    def a(o, c, k="painted_metal"):
        p.append(s3d.material(o, k, color=c))

    c = "#e3e0d6"
    q = "#a6abb3"
    a(bx("left_side", 18, 580, 870, -371, 0, 435), c)
    a(bx("right_side", 18, 580, 870, 371, 0, 435), c)
    a(bx("bottom_panel", 724, 580, 18, z=9), c)
    a(bx("top_panel", 724, 580, 18, z=861), c)
    a(bx("back_panel", 724, 6, 834, y=-287, z=435), "#a89e8f", "plastic")
    a(bx("cabinet_ceiling", 724, 574, 10, y=-3, z=847), "#a89e8f", "plastic")
    for sign, side in ((-1, "left"), (1, "right")):
        for nm, z in (("upper", 653), ("lower", 201)):
            a(bx(side + "_hinge_leaf_" + nm, 3, 32, 78, sign * 381.5, 289.5, z), q, "steel")
            a(cy(side + "_" + nm + "_hinge_knuckle", 5, 30, sign * 375, 310, z), q, "steel")
            a(bx(side + "_" + nm + "_hinge_bridge", 2, 6, 30, sign * 380, 307, z), q, "steel")
    return s3d.group("carcass", *p)


def door_part(name, sign):
    p = []
    c = "#e3e0d6"
    q = "#a6abb3"

    def a(o, col, k="painted_metal"):
        p.append(s3d.material(o, k, color=col))

    def x(v):
        return sign * (5 + v)

    a(bx("outer_stile", 70, 20, 838, x(35), 0, 419), c)
    a(bx("inner_stile", 70, 20, 838, x(333), 0, 419), c)
    a(bx("bottom_rail", 228, 20, 70, x(184), 0, 35), c)
    a(bx("top_rail", 228, 20, 70, x(184), 0, 803), c)
    a(bx("center_panel", 228, 10, 698, x(184), -4, 419), "#d3d1c7", "plastic")
    for nm, z in (("upper_hinge", 653), ("lower_hinge", 185)):
        a(bx(nm + "_leaf", 3, 16, 78, sign * 1.5, -1, z), q, "steel")
        a(cy(nm + "_knuckle_top", 5, 24, z=z + 27), q, "steel")
        a(cy(nm + "_knuckle_bottom", 5, 24, z=z - 27), q, "steel")
    return s3d.group(name, *p)


def knob_part(name):
    q = "#a6abb3"
    return s3d.group(
        name,
        s3d.material(cy("backplate", 10, 3, y=1.5, rx=-90), "steel", color=q),
        s3d.material(cy("stem", 4, 12, y=9, rx=-90), "steel", color=q),
        s3d.material(s3d.at(s3d.sphere("knob_head", 28), y=25.92, z=-14), "steel", color=q),
    )

import sand3d as s3d


def pendant_ceiling_light():
    canopy = canopy_part()
    hanger = hanger_part()
    shade = s3d.at(shade_part(), on=s3d.local(hanger, 0, 0, -695))
    carrier = s3d.group("hanger_and_shade", hanger, shade)
    f = s3d.local(canopy, 0, 0, 0)
    carrier = s3d.at(carrier, on=f)
    s3d.joint("canopy_swivel", carrier, f, kind="revolute", axis="+X", range=(-42.9718, 42.9718))
    return s3d.assembly("pendant_ceiling_light", canopy, carrier)


def brass(ob):
    return s3d.material(ob, "brass", color="#a89466")


def black(ob):
    return s3d.material(ob, "fabric", color="#1a1a1c")


def cream(ob):
    return s3d.material(ob, "ceramic", color="#e6e0d4")


def dark(ob):
    return s3d.material(ob, "plastic", color="#242426")


def canopy_part():
    shell = brass(
        s3d.revolve(
            "canopy_shell",
            [(10, 12), (26, 14), (44, 19), (58, 27), (61, 34), (59, 31), (6, 32), (6, 15)],
        )
    )
    left = brass(s3d.at(s3d.extrude("clevis_left", s3d.rect(9, 24), 30, both=True), x=-19))
    right = brass(s3d.at(s3d.extrude("clevis_right", s3d.rect(9, 24), 30, both=True), x=19))
    nipple = brass(s3d.at(s3d.extrude("ceiling_nipple", s3d.circle(24), 14, both=True), z=33))
    return s3d.group("canopy", shell, left, right, nipple)


def hanger_part():
    barrel = brass(s3d.at(s3d.extrude("trunnion_barrel", s3d.circle(13), 29, both=True), ry=90))
    stem = brass(s3d.at(s3d.extrude("swivel_stem", s3d.circle(20), 22, both=True), z=-14))
    grip = brass(s3d.at(s3d.extrude("cord_grip", s3d.circle(13), 18, both=True), z=-34))
    cord = black(s3d.at(s3d.extrude("fabric_cord", s3d.circle(9), 652, both=True), z=-369))
    return s3d.group("hanger", barrel, stem, grip, cord)


def shade_part():
    collar = brass(s3d.at(s3d.extrude("shade_collar", s3d.circle(44), 28, both=True), z=-14))
    socket = dark(s3d.at(s3d.extrude("socket_body", s3d.circle(36), 48, both=True), z=-38))
    outer = [(24, -18), (52, -36), (90, -72), (126, -112), (152, -148), (160, -170)]
    inner = [(152, -166), (145, -147), (119, -113), (84, -75), (46, -40), (18, -22)]
    dome = cream(s3d.revolve("dome_shade", outer + inner))
    return s3d.group("shade", collar, socket, dome)

import sand3d as s3d


def flip_top_lighter():
    case = outer_case()
    f = s3d.local(case, x=-19.35, z=41)
    lidpart = s3d.at(lid(), on=f)
    s3d.joint("lid_hinge", lidpart, f, kind="revolute", axis="-Y", range=(0, 114.59))
    f = s3d.local(case, z=1)
    ins = s3d.at(insert(), on=f)
    s3d.joint("insert_slide", ins, f, kind="prismatic", axis="+Z", range=(0, 29))
    f = s3d.local(ins, x=6.9, z=38.2)
    wh = s3d.at(striker_wheel(), on=f)
    s3d.joint("wheel_spin", wh, f, kind="continuous", axis="+Y")
    return s3d.assembly("flip_top_lighter", case, lidpart, ins, wh)


def outer_case():
    def chrome(o):
        return s3d.material(o, "chrome", color="#c2c7d1")

    def dark(o):
        return s3d.material(o, "steel", color="#525459")

    a = [chrome(s3d.at(s3d.extrude("case_floor", s3d.rect(37.2, 12.4), 1, both=True), z=0.5))]
    for n, x in [("case_side_0", -18.1), ("case_side_1", 18.1)]:
        a.append(chrome(s3d.at(s3d.extrude(n, s3d.rect(1, 12.4), 40, both=True), x=x, z=21)))
    for n, y in [("case_face_0", -5.7), ("case_face_1", 5.7)]:
        a.append(chrome(s3d.at(s3d.extrude(n, s3d.rect(35.2, 1), 40, both=True), y=y, z=21)))
    for n, z in [("case_knuckle_0", 27.5), ("case_knuckle_1", 36.5)]:
        a.append(
            dark(s3d.at(s3d.extrude(n, s3d.circle(2.3), 4.7, both=True), x=-18.75, z=z, rx=-90))
        )
    return s3d.group("outer_case", *a)


def lid():
    def chrome(o):
        return s3d.material(o, "chrome", color="#c2c7d1")

    data = [
        ("lid_roof", 38, 13, 0.9, 19.85, 0, 13.05),
        ("lid_side_0", 0.9, 13, 17.1, 1.3, 0, 4.05),
        ("lid_side_1", 0.9, 13, 17.1, 37.1, 0, 4.05),
        ("lid_face_0", 36.2, 0.9, 17.1, 19.85, -6.05, 4.05),
        ("lid_face_1", 36.2, 0.9, 17.1, 19.85, 6.05, 4.05),
    ]
    a = [
        chrome(s3d.at(s3d.extrude(n, s3d.rect(w, d), h, both=True), x=x, y=y, z=z))
        for n, w, d, h, x, y, z in data
    ]
    a.append(
        s3d.material(
            s3d.at(s3d.extrude("lid_knuckle", s3d.circle(2.3), 4.7, both=True), z=5.5, rx=-90),
            "steel",
            color="#525459",
        )
    )
    return s3d.group("lid", *a)


def insert():
    def steel(o):
        return s3d.material(o, "steel", color="#a1a6ad")

    def dark(o):
        return s3d.material(o, "steel", color="#525459")

    a = [steel(s3d.at(s3d.extrude("insert_floor", s3d.rect(34.6, 9.4), 0.7, both=True), z=0.35))]
    for n, w, d, x, y in [
        ("insert_side_0", 0.7, 9.4, -16.95, 0),
        ("insert_side_1", 0.7, 9.4, 16.95, 0),
        ("insert_face_0", 33.2, 0.7, 0, -4.35),
        ("insert_face_1", 33.2, 0.7, 0, 4.35),
    ]:
        a.append(steel(s3d.at(s3d.extrude(n, s3d.rect(w, d), 36.8, both=True), x=x, y=y, z=19.45)))
    a.append(
        steel(
            s3d.at(s3d.extrude("chimney_floor", s3d.rect(16, 8.2), 0.7, both=True), x=-4.5, z=24.35)
        )
    )
    for n, w, d, x, y in [
        ("chimney_side_0", 0.7, 8.2, -12.15, 0),
        ("chimney_side_1", 0.7, 8.2, 3.15, 0),
        ("chimney_face_0", 14.6, 0.7, -4.5, -3.75),
        ("chimney_face_1", 14.6, 0.7, -4.5, 3.75),
    ]:
