def candy_vending_machine():
    body = body_part()
    children = [body]
    for i, z in enumerate((325, 625, 925)):
        f = s3d.local(body, 0, -148, z)
        dial = s3d.at(dial_part(i), on=f)
        s3d.joint(f"body_to_dial_{i}", dial, f, kind="continuous", axis="+Y")
        children.append(dial)
    f = s3d.local(body, 0, -150, 105)
    door = s3d.at(retrieval_door(), on=f)
    s3d.joint("body_to_door", door, f, kind="revolute", axis="+X", range=(0, 90))
    children.append(door)
    return s3d.assembly("candy_vending_machine", *children)


def body_part():
    case = s3d.at(s3d.extrude("main_case", s3d.rect(300, 300), 1200, both=True), z=600)
    bins = [
        s3d.at(s3d.extrude("bin_cut", s3d.rect(260, 260), 250, both=True), z=z)
        for z in (1025, 725, 425)
    ]
    retrieval = s3d.at(s3d.extrude("retrieval_cut", s3d.rect(260, 260), 200, both=True), z=150)
    openings = [
        s3d.at(s3d.extrude("front_cut", s3d.rect(220, 200), 150, both=True), y=-150, z=z)
        for z in (175, 475, 775, 1075)
    ]
    s3d.cut(case, bins, retrieval, openings)
    s3d.material(case, "plastic", color="#cc1a1a")
    w0 = s3d.at(s3d.extrude("window_0", s3d.rect(220, 10), 150, both=True), y=-145, z=475)
    w1 = s3d.at(s3d.extrude("window_1", s3d.rect(220, 10), 150, both=True), y=-145, z=775)
    w2 = s3d.at(s3d.extrude("window_2", s3d.rect(220, 10), 150, both=True), y=-145, z=1075)
    for w in (w0, w1, w2):
        s3d.material(w, "glass", color="#cce6ff", opacity=0.4)
    return s3d.group("body", case, w0, w1, w2)


def dial_part(i):
    dial = s3d.cylinder(f"dial_mesh_{i}", 70, 15)
    ridge = s3d.extrude(f"dial_ridge_{i}", s3d.rect(15, 70), 25)
    dial = s3d.join(dial, ridge)
