def frame_part(width=1000, height=1100, depth=90, stile=60, rail=60):
    dark = "#33383d"
    parts = []
    for name, x in (("left_stile", -(width - stile) / 2), ("right_stile", (width - stile) / 2)):
        b = s3d.at(s3d.extrude(name, s3d.rect(stile, depth), height, both=True), x=x)
        parts.append(s3d.material(b, "painted_metal", color=dark))
    for name, z in (("top_rail", (height - rail) / 2), ("bottom_rail", -(height - rail) / 2)):
        b = s3d.at(s3d.extrude(name, s3d.rect(width, depth), rail, both=True), z=z)
        parts.append(s3d.material(b, "painted_metal", color=dark))
    aperture = width - 2 * stile
    pitch = (height - 2 * rail) / 12
    for i in range(11):
        z = -(height - 2 * rail) / 2 + pitch * (i + 1)
        for side, x in (("left", -aperture / 2 + 11), ("right", aperture / 2 - 11)):
            b = s3d.at(
                s3d.extrude(f"{side}_bracket_{i + 1}", s3d.rect(22, 30), 24, both=True), x=x, z=z
            )
            parts.append(s3d.material(b, "painted_metal", color=dark))
    return s3d.group("frame", *parts)


def vane_part(span=720, chord=66, thickness=12, pin_radius=5, journal=12):
    yz = s3d.Frame(origin=(0, 0, 0), normal=(1, 0, 0))
    blade = s3d.extrude("blade", s3d.ellipse(chord, thickness), span, both=True, on=yz)
    pins = []
    for x in (-span / 2 - journal / 2, span / 2 + journal / 2):
        p = s3d.at(s3d.extrude("pin", s3d.circle(2 * pin_radius), journal, both=True), x=x, rx=90)
        pins.append(p)
    shape = s3d.join(blade, *pins)
    shape = s3d.material(shape, "aluminium", color="#ccd1d6")
    return s3d.group("vane", shape)

