def stage(sep, w, d, length, rungs, radius, typ):
    out = []
    for nm, x in (("left_rail", -sep / 2), ("right_rail", sep / 2)):
        ob = s3d.at(s3d.extrude(nm, s3d.rect(w, d), length, both=True), x=x, z=length / 2)
        out.append(s3d.material(ob, "aluminium", color="#c9cfd6"))
    for i, z in enumerate(rungs):
        ob = s3d.at(
            s3d.extrude("rung_%d" % i, s3d.circle(radius * 2), sep - w, both=True), z=z, ry=90
        )
        out.append(s3d.material(ob, "aluminium", color="#c9cfd6"))
    if typ:
        pd, cw, cd, sep2, sy, zs, ch = (
            (22, 24, 19, 290, 29, (1640, 1820), 110)
            if typ == 1
            else (19, 22, 16, 276, 29, (1460, 1620), 100)
        )
        wall = 3.5
        cl = 2
        front = pd / 2
        back = sy - cd / 2
        cf = sy + cd / 2
        bd = back - front
        sd = cf + cl - front
        bw = cw + 2 * cl + 2 * wall
        ox = cw / 2 + cl + wall / 2
        for j, z in enumerate(zs):
            for sign, side in ((-1, "left"), (1, "right")):
                cx = sign * sep2 / 2
                prefix = f"{side}_guide_{j}"
                for suffix, ww, dd, x, y in (
                    ("bridge", bw, bd, cx, front + bd / 2),
                    ("outer_wall", wall, sd, cx - ox, front + sd / 2),
                    ("inner_wall", wall, sd, cx + ox, front + sd / 2),
                ):
                    ob = s3d.at(
                        s3d.extrude(prefix + "_" + suffix, s3d.rect(ww, dd), ch, both=True),
                        x=x,
                        y=y,
                        z=z,
                    )
                    out.append(s3d.material(ob, "plastic", color="#2e3338"))
    return out


