import sand3d as s3d


def die_handling_lift_mast():
    mast = mast_part()
    carriage_f = s3d.local(mast, 0, -205, 900)
    carriage = s3d.at(carriage_part(), on=carriage_f)
    s3d.joint(
        "mast_to_carriage", carriage, carriage_f, kind="prismatic", axis="+Z", range=(0, 1000)
    )
    return s3d.assembly("die_handling_lift_mast", mast, carriage)


def mast_part():
    dark = s3d.material(
        s3d.extrude("base_plinth", s3d.rect(1380, 820), 120, both=True), "steel", color="#141516"
    )
    dark = s3d.at(dark, y=120, z=60)
    rear = s3d.material(
        s3d.at(
            s3d.extrude("rear_counterweight", s3d.rect(1220, 340), 320, both=True), y=430, z=220
        ),
        "steel",
        color="#141516",
    )
    objs = [dark, rear]
    warm = "#474c4f"
    polish = "#adb3ad"
    for side, x in enumerate((-530, 530)):
        a = s3d.at(s3d.extrude(f"upright_{side}", s3d.rect(140, 180), 2700, both=True), x=x, z=1410)
        objs.append(s3d.material(a, "steel", color=warm))
        a = s3d.at(
            s3d.extrude(f"guide_rail_{side}", s3d.rect(75, 55), 2420, both=True),
            x=(430 if x > 0 else -430),
            y=-105,
            z=1420,
        )
        objs.append(s3d.material(a, "steel", color=polish))

    def beam(name, w, d, h, x, y, z, color):
        a = s3d.at(s3d.extrude(name, s3d.rect(w, d), h, both=True), x=x, y=y, z=z)
        return s3d.material(a, "steel", color=color)

    objs += [
        beam("top_header", 1220, 180, 160, 0, 0, 2720, warm),
        beam("lower_tie", 1160, 140, 120, 0, 30, 430, warm),
        beam("upper_tie", 1100, 120, 100, 0, 70, 2120, warm),
        beam("guard_lower_rail", 1040, 80, 70, 0, 120, 660, "#141516"),
        beam("guard_upper_rail", 1040, 80, 70, 0, 120, 2430, "#141516"),
    ]
    for i, x in enumerate((-320, -160, 0, 160, 320)):
        objs.append(beam(f"guard_bar_{i}", 35, 50, 1820, x, 130, 1545, "#141516"))
    return s3d.group("mast", *objs)


def carriage_part():
    yellow = "#f29e14"
    warm = "#474c4f"
    dark = "#141516"
    rubber = "#040403"

    def beam(name, w, d, h, x, y, z, color, kind="steel"):
        a = s3d.at(s3d.extrude(name, s3d.rect(w, d), h, both=True), x=x, y=y, z=z)
        return s3d.material(a, kind, color=color)

    objs = [
        beam("faceplate", 1380, 85, 620, 0, 0, 0, yellow, "plastic"),
        beam("top_beam", 1550, 120, 120, 0, -5, 350, yellow, "plastic"),
        beam("bottom_beam", 1550, 120, 120, 0, -5, -350, yellow, "plastic"),
    ]
    for side, x in enumerate((-735, 735)):
        objs.append(beam(f"side_cheek_{side}", 110, 140, 780, x, -5, 0, yellow, "plastic"))
    for i, x in enumerate((-460, 0, 460)):
        objs.append(beam(f"face_rib_{i}", 70, 105, 580, x, -65, 0, warm))
    for side, x in enumerate((-420, 420)):
        objs += [
            beam(f"arm_socket_{side}", 280, 180, 240, x, -80, -370, yellow, "plastic"),
            beam(f"load_arm_{side}", 200, 850, 120, x, -465, -470, warm),
            beam(f"arm_nose_{side}", 200, 70, 90, x, -925, -450, dark),
        ]
    for side, x in enumerate((-430, 430)):
        for level, z in (("lower", -240), ("upper", 240)):
            roller = s3d.at(
                s3d.extrude(f"{level}_roller_{side}", s3d.circle(70), 90, both=True),
                x=x,
                y=37.5,
                z=z,
                ry=90,
            )
            objs.append(s3d.material(roller, "rubber", color=rubber))
            objs.append(beam(f"{level}_roller_boss_{side}", 130, 80, 100, x, 5, z, dark))
    return s3d.group("carriage", *objs)

import sand3d as s3d
import math


def convertible_hand_truck():
    frame = main_frame()
    plate = s3d.at(primary_nose_plate(), on=s3d.local(frame, 0, 0, 0))
    frame = s3d.group("frame_and_fixed_plate", frame, plate)
    f = s3d.local(plate, 0, 242, 0)
    toe = s3d.at(secondary_toe_section(), on=f)
    s3d.joint("nose_plate_to_secondary_toe", toe, f, kind="revolute", axis="+X", range=(0, 180))
    f = s3d.local(frame, -260, -55, 300)
    left = s3d.at(left_rear_wheel(), on=f)
    s3d.joint("frame_to_left_wheel", left, f, kind="continuous", axis="+X")
    f = s3d.local(frame, 260, -55, 300)
    right = s3d.at(right_rear_wheel(), on=f)
    s3d.joint("frame_to_right_wheel", right, f, kind="continuous", axis="+X")
    return s3d.assembly("convertible_hand_truck", frame, toe, left, right)


